begin;
create view public.engineering_finance_executive_dashboard with(security_invoker=true) as
select d.tenant_id,d.company_id,d.work_id,d.work_name,d.work_status,d.original_contract_value,d.addenda_net,d.updated_contract_value,d.measured_gross,d.retained_amount,d.measured_net,d.gross_balance,d.measured_percent,d.production_quantity,d.production_value,coalesce(r.planned_revenue,0)::numeric(18,2) planned_revenue,coalesce(r.actual_revenue,0)::numeric(18,2) actual_revenue,coalesce(r.variance,0)::numeric(18,2) revenue_variance,coalesce(r.realization_percent,0) revenue_realization_percent,coalesce(a.receivable_total,0)::numeric(18,2) receivable_total,coalesce(a.received_total,0)::numeric(18,2) received_total,coalesce(a.outstanding_total,0)::numeric(18,2) outstanding_total,coalesce(a.overdue_total,0)::numeric(18,2) overdue_total,coalesce(a.overdue_count,0) overdue_count,coalesce(a.max_days_overdue,0) max_days_overdue,coalesce(a.overdue_percent,0) overdue_percent,coalesce(p.future_projected_revenue,0)::numeric(18,2) future_projected_revenue,coalesce(x.alert_count,0) alert_count,coalesce(x.critical_count,0) critical_alert_count
from public.engineering_work_dashboard d left join public.engineering_revenue_dashboard r on r.tenant_id=d.tenant_id and r.company_id=d.company_id and r.work_id=d.work_id left join public.engineering_receivables_risk_dashboard a on a.tenant_id=d.tenant_id and a.company_id=d.company_id and a.work_id=d.work_id left join(select tenant_id,company_id,work_id,sum(projected_amount) future_projected_revenue from public.engineering_revenue_projections where status='active' group by tenant_id,company_id,work_id)p on p.tenant_id=d.tenant_id and p.company_id=d.company_id and p.work_id=d.work_id left join(select tenant_id,company_id,work_id,count(*) alert_count,count(*) filter(where severity='critical') critical_count from public.financial_attention_alerts where work_id is not null group by tenant_id,company_id,work_id)x on x.tenant_id=d.tenant_id and x.company_id=d.company_id and x.work_id=d.work_id;
create view public.engineering_finance_company_executive with(security_invoker=true) as select tenant_id,company_id,count(*) work_count,sum(updated_contract_value)::numeric(18,2) updated_contract_value,sum(measured_gross)::numeric(18,2) measured_gross,sum(measured_net)::numeric(18,2) measured_net,sum(gross_balance)::numeric(18,2) contract_balance,sum(production_value)::numeric(18,2) production_value,sum(planned_revenue)::numeric(18,2) planned_revenue,sum(actual_revenue)::numeric(18,2) actual_revenue,sum(receivable_total)::numeric(18,2) receivable_total,sum(received_total)::numeric(18,2) received_total,sum(outstanding_total)::numeric(18,2) outstanding_total,sum(overdue_total)::numeric(18,2) overdue_total,sum(future_projected_revenue)::numeric(18,2) future_projected_revenue,sum(alert_count) alert_count,sum(critical_alert_count) critical_alert_count from public.engineering_finance_executive_dashboard group by tenant_id,company_id;
commit;